CREATE TABLE corrective_actions (id integer(32,0) NOT NULL, report_id integer(32,0), action_description text NOT NULL, action_type character varying(50), effectiveness_rating character varying(20), estimated_cost numeric(12,2), implementation_time_days integer(32,0), responsible_user_id integer(32,0), priority character varying(20), is_selected boolean, selection_criteria text, validation_plan text, validation_criteria text, created_at timestamp without time zone, updated_at timestamp without time zone, implementation_status character varying(50), planned_start_date date, actual_start_date date, planned_completion_date date, actual_completion_date date, progress_percentage integer(32,0), approver_user_id integer(32,0), implementation_notes text, validation_results text, is_effective boolean);